import itertools,json
jobs='ABCDE'
slot=dict(zip(jobs,[[0,1,4,11,3],[2,3,3,2,5],[4,8,2,10,8],[3,2,11,3,4],[10,6,10,10,4]]))
trans=dict(zip(jobs,[[0,3,3,0,5],[5,0,4,2,0],[2,2,0,2,5],[0,5,5,0,5],[1,4,3,1,0]]))
def nominal(p):
 return sum(slot[j][i] for i,j in enumerate(p))+sum(trans[a][jobs.index(b)] for a,b in zip(p,p[1:]))
def legal(p,s):
 pos={j:p.index(j)+1 for j in jobs}
 if pos['A']>=pos['D']: return False
 return {'rain':pos['D']!=1 and pos['A']!=1,'road':pos['C']!=4 and pos['E']!=2,'lift':pos['A']!=1 and pos['B']!=1}[s]
def penalty(p,s):
 return {'rain':6*max(0,p.index('C')),'road':6*max(0,p.index('D')+1-3),'lift':10*max(0,p.index('E')+1-2)}[s]
results=[]
for p in itertools.permutations(jobs):
 if p.index('A')>p.index('D'):continue
 neighbors=[(p,0)]
 for i,j in itertools.combinations(range(5),2):
  q=list(p);q[i],q[j]=q[j],q[i];neighbors.append((tuple(q),1))
 best={}
 for s in ['rain','road','lift']:
  options=[(nominal(q)+penalty(q,s)+sw,''.join(q)) for q,sw in neighbors if legal(q,s)]
  if not options:break
  best[s]=min(options)
 if len(best)==3:results.append((nominal(p)+max(v[0] for v in best.values()),''.join(p),best))
results.sort()
score,p,best=results[0]
print(json.dumps({'roster':p,'score':score,'repairs':{s:v[1] for s,v in best.items()},'repair_costs':{s:v[0] for s,v in best.items()},'feasible_count':len(results),'next_score':min(r[0] for r in results if r[0]>score)}))
print('publication nominal:',nominal(p),'optimal ties:',sum(r[0]==score for r in results))
for s,(c,q) in best.items(): print(s,q,'nominal',nominal(q),'penalty',penalty(q,s),'exchange',int(q!=p),'cost',c)

